export const DEVELOPMENT_NAMES = Object.freeze({bakery:'Piekarnia',dairy:'Mleczarnia',slaughterhouse:'Rzeźnia',fisher:'Rybak',leatherworks:'Zakład skórzany',academy:'Akademia',barracks:'Koszary',farm:'Gospodarstwo',warehouse:'Magazyn',theatre:'Teatr',windmill:'Młyn',lumber:'Drwale',quarry:'Kamieniołom',sawmill:'Tartak'});
export const GOODS_NAMES = Object.freeze({wood:'Drewno',stone:'Kamień',planks:'Deski',grain:'Zboże',vegetables:'Warzywa',livestock:'Żywiec',rawMilk:'Surowe mleko',sourMilk:'Kwaśne mleko',fish:'Ryby',smokedFish:'Ryba wędzona',fishPreserves:'Przetwory rybne',flour:'Mąka',pasteurizedMilk:'Mleko pasteryzowane',meat:'Mięso',leather:'Skóry',bread:'Chleb',cake:'Ciasto',cheese:'Ser',civilianClothes:'Ubrania cywilne',militaryClothes:'Stroje wojskowe',professorRobes:'Szaty profesorskie',food:'Żywność'});
export function developmentText(id, variables={}) { return (DEVELOPMENT_COPY[id] || '').replace(/\{([^}]+)\}/g,(match,key)=>Object.hasOwn(variables,key)?String(variables[key]):match); }
export function developmentBuildingCopy(id,state={},type='OPIS') {
  let variant='Podstawowy';
  if(id==='farm') variant=state.education?.discoveries?.cheese && Number(state.buildings?.farm?.level)>=6?'Po odkryciu sera':Number(state.buildings?.farm?.level)>=2?'Od poziomu 2':'Poziom 1';
  if(id==='bakery') variant=Object.keys(state.education?.discoveries||{}).some(key=>key!=='cake'&&/cake|pastry/i.test(key)&&state.education.discoveries[key])?'Po odkryciu ciasta':'Przed odkryciem ciasta';
  if(id==='leatherworks') variant=Number(state.buildings?.academy?.level)>0?'Po szatach':'Przed szatami';
  return developmentText(`BLD-${id.toUpperCase()}-${variant}-${type}`) || developmentText(`BLD-${id.toUpperCase()}-Podstawowy-${type}`);
}

// Keep reviewed explanations reachable from each building's actual information
// panel. These paragraphs describe existing mechanics; they never mutate state.
export function developmentBuildingInformation(id, state={}) {
  const supplementary = {
    academy: ['BLD-ACADEMY-ROUNDS-INFO', 'BLD-ACADEMY-INTERRUPTION-INFO', 'BLD-ACADEMY-RESCUE-INFO'],
    barracks: ['BLD-BARRACKS-RETURN-INFO'],
    warehouse: ['BLD-WAREHOUSE-MILK-OVERFLOW-INFO', 'BLD-WAREHOUSE-CONSTRUCTION-MEALS-INFO']
  };
  return [developmentBuildingCopy(id,state,'INFO'), ...(supplementary[id] || []).map(key=>developmentText(key))].filter(Boolean);
}
